function check(bool $condition,string $name): void {if(!$condition)throw new RuntimeException('FAIL: '.$name);echo "PASS: $name\n";}
function request(string $path,string $method='GET',mixed $data=null,string $token='',int $expected=200): mixed {
 $c=curl_init('http://127.0.0.1:8001/api'.$path);$headers=['Accept: application/json'];if($token)$headers[]='Authorization: Bearer '.$token;
 if($data!==null&&!is_array($data)||is_array($data)&&!isset($data['image'])) {if($data!==null){$headers[]='Content-Type: application/json';$data=json_encode($data);}}
 curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>10]);if($data!==null)curl_setopt($c,CURLOPT_POSTFIELDS,$data);
 $raw=curl_exec($c);$status=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);$decoded=json_decode($raw,true);
 if($status!==$expected||!is_array($decoded))throw new RuntimeException("$method $path: expected $expected, got $status: ".substr($raw,0,400));return $decoded['data'];
}
$stamp=bin2hex(random_bytes(5));$email='test-'.$stamp.'@example.test';$pass='Test-'.bin2hex(random_bytes(10));
$auth=request('/auth/register','POST',['name'=>'Test Customer','email'=>$email,'phone'=>'081234567890','birth_date'=>'1995-01-01','password'=>$pass],'',201);$token=$auth['token'];$uid=$auth['user']['id'];
check(request('/me','GET',null,$token)['email']===$email,'Registration + JWT authentication');
request('/auth/login','POST',['email'=>$email,'password'=>'wrong'],'',401);check(true,'Wrong password rejected');
$adminEmail='admin-'.$stamp.'@example.test';query("INSERT INTO users(name,email,phone,password,birth_date,role) VALUES('Test Admin',?,'081234567890',?,'1990-01-01','admin')",[$adminEmail,password_hash($pass,PASSWORD_BCRYPT)]);
$admin=request('/auth/login','POST',['email'=>$adminEmail,'password'=>$pass])['token'];
request('/admin/products','GET',null,$token,403);check(true,'Customer cannot access admin');
request('/admin/settings','PUT',['bank_name'=>'TEST ONLY - DO NOT PAY','bank_account'=>'TEST-ACCOUNT','bank_holder'=>'TEST FIXTURE','terea_enabled'=>'0'],$admin);
$items=request('/products?q=SQ40')['items'];check(count($items)===1&&$items[0]['name']==='Instax SQ40','Product search');
