check(count(array_filter(request('/categories'),fn($c)=>$c['is_age_restricted']))===0,'Restricted category disabled by default');
$p=request('/products/1');$vid=$p['variants'][0]['id'];$initialStock=(int)$p['stock'];
request('/cart','POST',['variant_id'=>$vid,'qty'=>999],$token,422);check(true,'Cart rejects insufficient stock');
request('/cart','POST',['variant_id'=>$vid,'qty'=>2],$token);$cart=request('/cart','GET',null,$token);check($cart[0]['qty']===2,'Cart persisted');
$a=request('/addresses','POST',['label'=>'Test','recipient'=>'Test Customer','phone'=>'081234567890','address'=>'Alamat pengujian','city'=>'Jakarta','province'=>'DKI Jakarta','postal_code'=>'12345','is_default'=>1],$token);$aid=$a[0]['id'];
$o=request('/orders','POST',['address_id'=>$aid,'courier'=>'reguler'],$token,201);
check((int)$o['total']===(int)$p['price']*2+20000,'Checkout uses server prices and shipping');
check((int)request('/products/1')['stock']===$initialStock-2,'Checkout deducts stock');
check(count(request('/cart','GET',null,$token))===0,'Checkout clears cart');
request('/orders/'.$o['id'],'GET',null,$admin,404);check(true,'Order ownership enforced');
request('/orders/'.$o['id'].'/cancel','POST',null,$token);check((int)request('/products/1')['stock']===$initialStock,'Cancellation restores stock');
request('/orders/'.$o['id'].'/cancel','POST',null,$token,422);check((int)request('/products/1')['stock']===$initialStock,'Repeated cancellation cannot duplicate stock');
request('/cart','POST',['variant_id'=>$vid,'qty'=>1],$token);$o=request('/orders','POST',['address_id'=>$aid,'courier'=>'express'],$token,201);
$image=new CURLFile(realpath(__DIR__.'/../../brand/logo.png'),'image/png','test.png');
request('/orders/'.$o['id'].'/payment-proof','POST',['image'=>$image],$token);
check(request('/orders/'.$o['id'],'GET',null,$token)['status']==='menunggu_verifikasi','Payment proof upload');
request('/admin/orders/'.$o['id'],'PUT',['status'=>'dikirim','tracking_number'=>'INVALID'],$admin,422);check(true,'Invalid status transition rejected');
request('/admin/orders/'.$o['id'],'PUT',['status'=>'diproses'],$admin);
request('/orders/'.$o['id'].'/cancel','POST',null,$token,422);check(true,'Processed order cannot be cancelled');
request('/admin/orders/'.$o['id'],'PUT',['status'=>'dikirim'],$admin,422);check(true,'Shipment requires tracking');
request('/admin/orders/'.$o['id'],'PUT',['status'=>'dikirim','tracking_number'=>'TEST-123'],$admin);
request('/orders/'.$o['id'].'/complete','POST',null,$token);check(request('/orders/'.$o['id'],'GET',null,$token)['status']==='selesai','Payment to fulfillment complete flow');
check(count(request('/admin/report?period=monthly','GET',null,$admin))>0,'Monthly sales report');
request('/cart','POST',['variant_id'=>$vid,'qty'=>1],$token);$expired=request('/orders','POST',['address_id'=>$aid,'courier'=>'reguler'],$token,201);query('UPDATE orders SET expires_at=DATE_SUB(NOW(),INTERVAL 1 HOUR) WHERE id=?',[$expired['id']]);
check(request('/orders/'.$expired['id'],'GET',null,$token)['status']==='dibatalkan','Expired unpaid order cancels automatically');
check((int)request('/products/1')['stock']===$initialStock-1,'Expiry restores stock exactly once');
request('/me/age-verification','POST',['image'=>$image],$token,403);check(true,'Disabled age verification rejects uploads');
request('/admin/settings','PUT',['terea_enabled'=>'1'],$admin);check(count(array_filter(request('/categories'),fn($c)=>$c['is_age_restricted']))===1,'Feature flag changes category visibility');
request('/me/age-verification','POST',['image'=>$image],$token);check(request('/me','GET',null,$token)['age_status']==='menunggu','Age verification submission');
check(str_starts_with(request('/admin/users/'.$uid.'/identity','GET',null,$admin),'data:image/png;base64,'),'Encrypted identity can be decrypted only by admin');
request('/admin/users/'.$uid.'/identity','GET',null,$token,403);check(true,'Customer cannot retrieve private identity');
request('/admin/users/'.$uid,'PUT',['age_status'=>'disetujui'],$admin);check(request('/me','GET',null,$token)['age_status']==='disetujui','Admin age approval');
$product=request('/admin/products/1','GET',null,$admin);$product['description'].=' Test';$product['images']=array_column($product['images'],'image_url');$product=request('/admin/products/1','PUT',$product,$admin);check(str_ends_with($product['description'],'Test'),'Admin product CRUD');
request('/admin/campaign','GET',null,$token,403);check(true,'Customers cannot manage campaigns');
$event=['enabled'=>true,'label'=>'TEST EVENT','title'=>'Event test fixture','starts_at'=>date('Y-m-d H:i',time()+3600),'ends_at'=>date('Y-m-d H:i',time()+7200),'discount_percent'=>10,'product_ids'=>[1]];
request('/admin/campaign','PUT',$event,$admin);
check(request('/campaign')['mode']==='scheduled'&&request('/products/1')['sale_price']===null,'Scheduled campaign does not discount early');
request('/admin/campaign','PUT',[...$event,'discount_percent'=>100],$admin,422);check(true,'Invalid discount rejected');
request('/admin/campaign','PUT',[...$event,'starts_at'=>'2026-02-30 09:00'],$admin,422);check(true,'Invalid calendar date rejected');
$event['starts_at']=date('Y-m-d H:i',time()-3600);$event['ends_at']=date('Y-m-d H:i',time()+3600);request('/admin/campaign','PUT',$event,$admin);
$discounted=(int)floor((int)$p['price']*.9);
check(request('/campaign')['mode']==='live'&&request('/products/1')['sale_price']===$discounted,'Live campaign exposes discounted product price');
check(request('/products?sale=1')['total']===1,'Event catalogue includes only selected products');
check(in_array(1,array_column(request('/products?max='.$discounted)['items'],'id'),true),'Price filtering uses sale prices');
$variantProduct=request('/admin/products/1','GET',null,$admin);$variantProduct['images']=array_column($variantProduct['images'],'image_url');$variantProduct['variants'][0]['price_override']=(int)$p['price']+100000;
