request('/orders','POST',['address_id'=>$aid,'courier'=>'reguler','expected_total'=>$variantSale+20001],$token,422);
check((int)request('/products/1')['stock']===$stockBefore&&count(request('/cart','GET',null,$token))===1,'Changed total rejects checkout without consuming stock or cart');
$promoOrder=request('/orders','POST',['address_id'=>$aid,'courier'=>'reguler','expected_total'=>$variantSale+20000],$token,201);
check((int)$promoOrder['subtotal']===$variantSale,'Checkout applies server campaign price');
$event['starts_at']=date('Y-m-d H:i',time()-7200);$event['ends_at']=date('Y-m-d H:i',time()-3600);request('/admin/campaign','PUT',$event,$admin);
check(request('/campaign')['mode']==='ended'&&request('/products/1')['sale_price']===null,'Expired event returns regular prices');
check((int)request('/orders/'.$promoOrder['id'],'GET',null,$token)['items'][0]['price']===$variantSale,'Existing order preserves discounted snapshot after expiry');
request('/orders/'.$promoOrder['id'].'/cancel','POST',null,$token);
request('/admin/categories/1','PUT',['name'=>'Instax Camera','slug'=>'instax-camera','is_active'=>1,'is_age_restricted'=>1],$admin);
request('/admin/campaign','PUT',$event,$admin,422);check(true,'Restricted categories cannot participate in events');
request('/admin/categories/1','PUT',['name'=>'Instax Camera','slug'=>'instax-camera','is_active'=>1,'is_age_restricted'=>0],$admin);
$variantProduct=request('/admin/products/1','GET',null,$admin);$variantProduct['images']=array_column($variantProduct['images'],'image_url');$variantProduct['variants'][0]['price_override']=null;request('/admin/products/1','PUT',$variantProduct,$admin);
request('/admin/campaign','PUT',[...$event,'enabled'=>false],$admin);
request('/auth/logout','POST',null,$token);request('/me','GET',null,$token,401);check(true,'Logout revokes token');
echo "All integration checks passed. Test data exists only in ipt_store_test.\n";
